import{_ as n,o as a,c as s,a5 as t}from"./chunks/framework.BPFk9-tb.js";const d=JSON.parse('{"title":"go-plugin教程","description":"","frontmatter":{"date":"2022-11-21T15:26:32","title":"go-plugin教程"},"headers":[{"level":2,"title":"Intro","slug":"intro","link":"#intro","children":[]},{"level":2,"title":"Basic plugin","slug":"basic-plugin","link":"#basic-plugin","children":[]},{"level":2,"title":"Basic concepts","slug":"basic-concepts","link":"#basic-concepts","children":[{"level":3,"title":"Server","slug":"server","link":"#server","children":[]},{"level":3,"title":"Client","slug":"client","link":"#client","children":[]}]},{"level":2,"title":"Implementation","slug":"implementation","link":"#implementation","children":[{"level":3,"title":"The main function","slug":"the-main-function","link":"#the-main-function","children":[{"level":4,"title":"Logger","slug":"logger","link":"#logger","children":[]},{"level":4,"title":"NewClient","slug":"newclient","link":"#newclient","children":[]}]},{"level":3,"title":"The Interface","slug":"the-interface","link":"#the-interface","children":[]},{"level":3,"title":"The Implementation","slug":"the-implementation","link":"#the-implementation","children":[]}]},{"level":2,"title":"The API","slug":"the-api","link":"#the-api","children":[]},{"level":2,"title":"Generate the code","slug":"generate-the-code","link":"#generate-the-code","children":[]},{"level":2,"title":"Writing the GRPC Client","slug":"writing-the-grpc-client","link":"#writing-the-grpc-client","children":[]},{"level":2,"title":"Writing the GRPC Server","slug":"writing-the-grpc-server","link":"#writing-the-grpc-server","children":[]},{"level":2,"title":"Writing the plugin itself","slug":"writing-the-plugin-itself","link":"#writing-the-plugin-itself","children":[]},{"level":2,"title":"Calling it all in the main","slug":"calling-it-all-in-the-main","link":"#calling-it-all-in-the-main","children":[]},{"level":2,"title":"Conclusion","slug":"conclusion","link":"#conclusion","children":[]}],"relativePath":"posts/go/go-plugin.md","filePath":"posts/go/go-plugin.md"}'),i={name:"posts/go/go-plugin.md"};function l(o,e,p,r,c,h){return a(),s("div",null,[...e[0]||(e[0]=[t(`<p><a href="https://cheppers.com/post/hashicorps-go-plugin-extensive-tutorial/" target="_blank" rel="noreferrer">原文 HashiCorp&#39;s go-plugin extensive tutorial</a></p><h2 id="intro" tabindex="-1">Intro <a class="header-anchor" href="#intro" aria-label="Permalink to &quot;Intro&quot;">​</a></h2><p>If you don&#39;t know what go-plugin is, don&#39;t worry, here is a small introduction on the subject matter:</p><p>Back in the old days when Go didn&#39;t have the <code>plugin</code> package, HashiCorp was desperately looking for a way to use plugins.</p><p>In the old days, Lua plus Go wasn&#39;t really a thing yet, and to be honest, nobody wants to write Lua ( joking!).</p><p>And thus Mitchell had this brilliant idea of using RPC over the local network to serve a local interface as something that could easily be implemented with any other language that supported RPC. This sounds convoluted but has many benefits! For example, your code will never crash because of a plugin and the ability to use any language to implement a plugin. Not just Go.</p><p>It has been a battle-hardened solution for years now and is being actively used by Terraform, Vault, Consule, and especially Packer. All using go-plugin in order to provide a much needed flexibility. Writing a plugin is easy. Or so they say.</p><p>It can get complicated quickly, for example, if you are trying to use GRPC. You can lose sight of what exactly you&#39;ll need to implement, where and why; or utilizing various languages or using go-plugins in your own project and extending your CLI with pluggable components.</p><p>These are all nothing to sneeze at. Suddenly you&#39;ll find yourself with hundreds of lines of code pasted from various examples and yet nothing works. Or worse, it DOES work but you have no idea how. Then you find yourself needing to extend it with a new capability, or you find an elusive bug and can&#39;t trace its origins.</p><p>Fear not. I&#39;ll try to demystify things and draw a clear picture about how it works and how the pieces fit together.</p><p>Let&#39;s start at the beginning.</p><h2 id="basic-plugin" tabindex="-1">Basic plugin <a class="header-anchor" href="#basic-plugin" aria-label="Permalink to &quot;Basic plugin&quot;">​</a></h2><p>Let&#39;s start by writing a simple Go GRPC plugin. In fact, we can go through the basic example in the go-plugin’s repository which can be quite confusing when first starting out. We&#39;ll go step-by-step, and the switch to GRPC will be much easier!</p><h2 id="basic-concepts" tabindex="-1">Basic concepts <a class="header-anchor" href="#basic-concepts" aria-label="Permalink to &quot;Basic concepts&quot;">​</a></h2><h3 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h3><p>In the case of plugins, the Server is the one serving the plugin&#39;s implementation. This means the server will have to provide the implementation to an interface.</p><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><p>The Client calls the server in order to execute the desired behavior. The underlying logic will connect to the server running on localhost on a random higher port, call the wanted function’s implementation and wait for a response. Once the response is received provide that back to the calling Client.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><h3 id="the-main-function" tabindex="-1">The main function <a class="header-anchor" href="#the-main-function" aria-label="Permalink to &quot;The main function&quot;">​</a></h3><h4 id="logger" tabindex="-1">Logger <a class="header-anchor" href="#logger" aria-label="Permalink to &quot;Logger&quot;">​</a></h4><p>The plugins defined here use stdout in a special way. If you aren&#39;t writing a Go based plugin, you will have to do that yourself by outputting something like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 1|1|tcp|127.0.0.1:1234|grpc</span></span></code></pre></div><p>We&#39;ll come back to this later. Suffice to say the framework will pick this up and will connect to the plugin based on the output. In order to get some output back, we must define a special logger:</p><p><code>// Create an hclog.Logger logger := hclog.New(&amp;hclog.LoggerOptions{ Name: &quot;plugin&quot;, Output: os.Stdout, Level: hclog.Debug, })</code></p><h4 id="newclient" tabindex="-1">NewClient <a class="header-anchor" href="#newclient" aria-label="Permalink to &quot;NewClient&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // We&#39;re a host! Start by launching the plugin process. client := plugin.NewClient(&amp;plugin.ClientConfig{</span></span>
<span class="line"><span>    HandshakeConfig: handshakeConfig,</span></span>
<span class="line"><span>    Plugins:         pluginMap,</span></span>
<span class="line"><span>    Cmd:             exec.Command(&quot;./plugin/greeter&quot;),</span></span>
<span class="line"><span>    Logger:          logger,</span></span>
<span class="line"><span>}) defer client.Kill()</span></span></code></pre></div><p>What is happening here? Let&#39;s see one by one: <strong>HandshakeConfig: handshakeConfig</strong>: This part is the handshake configuration of the plugin. It has a nice comment as well.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // handshakeConfigs are used to just do a basic handshake between</span><span> // a plugin and host. If the handshake fails, a user friendly error is shown.</span><span> // This prevents users from executing bad plugins or executing a plugin</span><span> // directory. It is a UX feature, not a security feature. var handshakeConfig = plugin.HandshakeConfig{</span></span>
<span class="line"><span>    ProtocolVersion:  1,</span></span>
<span class="line"><span>    MagicCookieKey:   &quot;BASIC_PLUGIN&quot;,</span></span>
<span class="line"><span>    MagicCookieValue: &quot;hello&quot;,</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <strong>ProtocolVersion</strong> here is used in order to maintain compatibility with your current plugin versions. It&#39;s basically like an API version. If you increase this, you will have two options. Don&#39;t accept lower protocol versions nor switch to the version number and use a different client implementation for a lower version than for a higher version. This way you will maintain backwards compatibility. The <strong>MagicCookieKey</strong> and <strong>MagicCookieValue</strong> are used for a basic handshake which the comment is talking about. You have to set this <strong>ONCE</strong> for your application. Never change it again, for if you do, your plugins will no longer work. For uniqueness sake, I suggest using UUID. <strong>Cmd</strong> is one of the most important parts about a plugin. Basically how plugins work is that they boil down to a compiled binary which is executed and starts an RPC server. This is where you will have to define the binary which will be executed and does all this. Since this is all happening locally, (please keep in mind that Go-plugins only support localhost, and for a good reason), these binaries will most likely sit next to your application&#39;s binary or in a pre-configured global location. Something like: <code>~/.config/my-app/plugins</code>. This is individual for each plugin of course. The plugins can be autoloaded via a discovery function given a path and a glob. And last but not least is the <code>Plugins</code> map. This map is used in order to identify a plugin called <code>Dispense</code>. This map is globally available and must stay consistent in order for all the plugins to work:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// pluginMap is the map of plugins we can dispense. var pluginMap = map[string]plugin.Pluglin   &quot;greeter&quot;: &amp;example.GreeterPlugin{}, }</span></span></code></pre></div><p>You can see that the key is the name of the plugin and the value is the plugin. We then proceed to create an RPC client:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Connect via RPC rpcClient, err := client.Client() if err != nil {</span></span>
<span class="line"><span>    log.Fatal(err)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Nothing fancy about this one... Now comes the interesting part:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Request the plugin raw, err := rpcClient.Dispense(&quot;greeter&quot;) if err != nil {</span></span>
<span class="line"><span>    log.Fatal(err)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>What&#39;s happening here? Dispense will look in the above created map and search for the plugin. If it cannot find it, it will throw an error at us. If it does find it, it will cast this plugin to an RPC or a GRPC type plugin. Then proceed to create an RPC or a GRPC client out of it. There is no call yet. This is just creating a client and parsing it to a respective representation. Now comes the magic:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // We should have a Greeter now! This feels like a normal interface</span><span> // implementation but is in fact over an RPC connection. greeter := raw.(example.Greeter) fmt.Println(greeter.Greet())</span></span></code></pre></div><p>Here we are type asserting our raw GRPC client into our own plugin type. This is so we can call the respective function on the plugin! Once that&#39;s done we will have a {client,struct,implementation} that can be called like a simple function. The implementation right now comes from greeter_impl.go, but that will change once protoc makes an appearance. Behind the scenes, go-plugin will do a bunch of hat tricks with multiplexing TCP connections as well as a remote procedure call to our plugin. Our plugin then will run the function, generate some kind of output, and will then send that back for the waiting client. The client will then proceed to parse the message into a given response type and will then return it back to the client’s callee. This concludes main.go for now.</p><h3 id="the-interface" tabindex="-1">The Interface <a class="header-anchor" href="#the-interface" aria-label="Permalink to &quot;The Interface&quot;">​</a></h3><p>Now let’s investigate the Interface. The interface is used to provide calling details. This interface will be what defines our plugins’ capabilities. How does our look like?</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Greeter is the interface that we&#39;re exposing as a plugin. type Greeter interface {</span></span>
<span class="line"><span>    Greet() string</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This is pretty simple. It defines a function which will return a string typed value. Now, we will need a couple of things for this to work. Firstly we need something which defines the RPC workings. go-plugin is working with <code>net/http</code> inside. It also uses something called Yamux for connection multiplexing, but we needn’t worry about this detail. Implementing the RPC details looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Here is an implementation that talks over RPC type GreeterRPC struct {</span></span>
<span class="line"><span>    client *rpc.Client</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (g *GreeterRPC) Greet() string {</span></span>
<span class="line"><span>    var resp string</span></span>
<span class="line"><span>    err := g.client.Call(&quot;Plugin.Greet&quot;, new(interface{}), &amp;resp)</span></span>
<span class="line"><span>    if err != nil {</span></span>
<span class="line"><span>        // You usually want your interfaces to return errors. If they don&#39;t,</span></span>
<span class="line"><span>        // there isn&#39;t much other choice here.</span></span>
<span class="line"><span>        panic(err)</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return resp</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here the GreeterRPC struct is an RPC specific implementation that will handle communication over RPC. This is Client in this setup. In case of gRPC, this would look something like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // GRPCClient is an implementation of KV that talks over RPC. type GreeterGRPC struct{ client proto.GreeterClient }</span></span>
<span class="line"><span>func (m *GreeterGRPC) Greet() (string, error) {</span></span>
<span class="line"><span>    s, err := m.client.Greet(context.Background(), &amp;proto.Empty{})</span></span>
<span class="line"><span>    return s, err</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>What is happening here? What&#39;s Proto and what is GreeterClient? GRPC uses Google&#39;s protoc library to serialize and unserialize data.<code>proto.GreeterClient</code> is generated Go code by protoc. This code is a skeleton for which implementation detail will be replaced on run time. Well, the actual result will be used and not replaced as such. Back to our previous example. The RPC client calls a specific Plugin function called Greet for which the implementation will be provided by a Server that will be streamed back over the RPC protocol. The server is pretty easy to follow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Here is the RPC server that GreeterRPC talks to, conforming to</span><span> // the requirements of net/rpc type GreeterRPCServer struct {</span></span>
<span class="line"><span>    // This is the real implementation</span></span>
<span class="line"><span>    Impl Greeter</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Impl is the concrete implementation that will be called in the Server&#39;s implementation of the Greet plugin. Now we must define Greet on the RPCServer in order for it to be able to call the remote code. This looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> func (s *GreeterRPCServer) Greet(args interface{}, resp *string) error {</span></span>
<span class="line"><span>    *resp = s.Impl.Greet()</span></span>
<span class="line"><span>    return nil</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This is all still boilerplate for the RPC works. Now comes plugin. For this, the comment is actually quite good too:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // This is the implementation of plugin.Plugin so we can serve/consume this</span><span> //</span><span> // This has two methods: Server must return an RPC server for this plugin</span><span> // type. We construct a GreeterRPCServer for this.</span><span> //</span><span> // Client must return an implementation of our interface that communicates</span><span> // over an RPC client. We return GreeterRPC for this.</span><span> //</span><span> // Ignore MuxBroker. That is used to create more multiplexed streams on our</span><span> // plugin connection and is a more advanced use case. type GreeterPlugin struct {</span></span>
<span class="line"><span>    // Impl Injection</span></span>
<span class="line"><span>    Impl Greeter</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (p *GreeterPlugin) Server(*plugin.MuxBroker) (interface{}, error) {</span></span>
<span class="line"><span>    return &amp;GreeterRPCServer{Impl: p.Impl}, nil</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (GreeterPlugin) Client(b *plugin.MuxBroker, c *rpc.Client) (interface{}, error) {</span></span>
<span class="line"><span>    return &amp;GreeterRPC{client: c}, nil</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>What does this mean? So, remember: <code>GreeterRPCServer</code> is the one calling the actual implementation while Client is receiving the result of that call. The <code>GreeterPlugin</code> has the <code>Greeter</code> interface embedded just like the <code>RPCServer</code>. We will use the <code>GreeterPlugin</code> as a struct in the plugin map. This is the plugin that we will actually use. This is all still common stuff. These things will need to be visible for both. The plugin&#39;s implementation will use the interface to see what it needs to implement. The Client will use it see what to call and what API is available. Like, <code>Greet</code>. How does the implementation look like?</p><h3 id="the-implementation" tabindex="-1">The Implementation <a class="header-anchor" href="#the-implementation" aria-label="Permalink to &quot;The Implementation&quot;">​</a></h3><p>In a completely separate package, but which still has access to the interface definition, this plugin could be something like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Here is a real implementation of Greeter type GreeterHello struct {</span></span>
<span class="line"><span>    logger hclog.Logger</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (g *GreeterHello) Greet() string {</span></span>
<span class="line"><span>    g.logger.Debug(&quot;message from GreeterHello.Greet&quot;)</span></span>
<span class="line"><span>    return &quot;Hello!&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>We create a struct and then add the function to it which is defined by the plugin&#39;s interface. This interface, since it&#39;s required by both parties, could well sit in a common package outside of both programs. Something like a SDK. Both code could import it and use it as a common dependency. This way we have separated the interface from the plugin <strong>and</strong> the calling client. The <code>main</code> function could look something like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> logger := hclog.New(&amp;hclog.LoggerOptions{</span></span>
<span class="line"><span>    Level:      hclog.Trace,</span></span>
<span class="line"><span>    Output:     os.Stderr,</span></span>
<span class="line"><span>    JSONFormat: true,</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span>greeter := &amp;GreeterHello{</span></span>
<span class="line"><span>    logger: logger,</span></span>
<span class="line"><span>} // pluginMap is the map of plugins we can dispense. var pluginMap = map[string]plugin.Plugin{</span></span>
<span class="line"><span>    &quot;greeter&quot;: &amp;example.GreeterPlugin{Impl: greeter},</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>logger.Debug(&quot;message from plugin&quot;, &quot;foo&quot;, &quot;bar&quot;)</span></span>
<span class="line"><span>plugin.Serve(&amp;plugin.ServeConfig{</span></span>
<span class="line"><span>    HandshakeConfig: handshakeConfig,</span></span>
<span class="line"><span>    Plugins:         pluginMap,</span></span>
<span class="line"><span>})</span></span></code></pre></div><p>Notice two things that we need. One is the <code>handshakeConfig</code>. You can either define it here, with the same cookie details as you defined in the client code, or you can extract the handshake information into the SDK. This is up to you. Then the next interesting thing is the <code>plugin.Serve</code> method. This is where the magic happens. The plugins open up a RPC communication socket and over a hijacked <code>stdout</code>, broadcasts its availability to the calling Client in this format:</p><p><code>CORE-PROTOCOL-VERSION | APP-PROTOCOL-VERSION | NETWORK-TYPE | NETWORK-ADDR | PROTOCOL</code></p><p>For Go plugins, you don&#39;t have to concern yourself with this. <code>go-plugin</code> takes care of all this for you. For non-Go versions, we must take this into account. And before calling serve, we need to output this information to <code>stdout</code>. For example, a Python plugin must deal with this himself. Like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> # Output information print(&quot;1|1|tcp|127.0.0.1:1234|grpc&quot;) sys.stdout.flush()</span></span></code></pre></div><p>For GRPC plugins, it&#39;s also mandatory to implement a HealthChecker. How would all this look like with GRPC? It gets slightly more complicated but not too much. We need to use <code>protoc</code> to create a protocol description for our implementation, and then we will call that. Let&#39;s look at this now by converting the basic greeter example into GRPC.</p><h1 id="grpc-basic-plugin" tabindex="-1">GRPC Basic plugin <a class="header-anchor" href="#grpc-basic-plugin" aria-label="Permalink to &quot;GRPC Basic plugin&quot;">​</a></h1><p>The example that&#39;s under GRPC is quite elaborate and perhaps you don&#39;t need the Python part. I will focus on the basic RPC example into a GRPC example. That should not be a problem.</p><h2 id="the-api" tabindex="-1">The API <a class="header-anchor" href="#the-api" aria-label="Permalink to &quot;The API&quot;">​</a></h2><p>First and foremost, you will need to define an API to implement with <code>protoc</code>. For our basic example, the protoc file could look like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> syntax = &quot;proto3&quot;; package proto;</span></span>
<span class="line"><span>message GreetResponse {</span></span>
<span class="line"><span>    string message = 1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>message Empty {}</span></span>
<span class="line"><span>service GreeterService {</span></span>
<span class="line"><span>    rpc Greet(Empty) returns (GreetResponse);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The syntax is quite simple and readable. What this defines is a message, which is a response, that will contain a <code>message</code> with the type <code>string</code>. The <code>service</code> defines a service which has a method called <code>Greet</code>. The service definition is basically an interface for which we will be providing the concrete implementation through the plugin. To read more about protoc, visit this page: <a href="https://developers.google.com/protocol-buffers/" target="_blank" rel="noreferrer">Google Protocol Buffer</a>.</p><h2 id="generate-the-code" tabindex="-1">Generate the code <a class="header-anchor" href="#generate-the-code" aria-label="Permalink to &quot;Generate the code&quot;">​</a></h2><p>Now, with the protoc definition in hand, we need to generate the stubs that the local client implementation can call. That client call will then, through the remote procedure call, call the right function on the server which will have the concrete implementation at the ready. Run it and return the result in the specified format. Because the stub needs to be available by both parties, (the client AND the server), this needs to live in a shared location. Why? Because the client is calling the stub and the server is implementing the stub. Both need it in order to know what to call/implement. To generate the code, run this command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> protoc -I proto/ proto/greeter.proto --go_out=plugins=grpc:proto</span></span></code></pre></div><p>I encourage you to read the generated code. Much will make little sense at first. It will have a bunch of structs and defined things that the GRPC package will use in order to server the function. The interesting bits and pieces are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> func (m *GreetResponse) GetMessage() string {</span></span>
<span class="line"><span>    if m != nil {</span></span>
<span class="line"><span>        return m.Message</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return &quot;&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Which will get use the message inside the response.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> type GreeterServiceClient interface {</span></span>
<span class="line"><span>    Greet(ctx context.Context, in *Empty, opts ...grpc.CallOption) (*GreetResponse, error)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This is our ServiceClient interface which defines the Greet function’s topology. And lastly, this guy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> func RegisterGreeterServiceServer(s *grpc.Server, srv GreeterServiceServer) {</span></span>
<span class="line"><span>    s.RegisterService(&amp;_GreeterService_serviceDesc, srv)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Which we will need in order to register our implementation for the server. We can ignore the rest. ## The interface Much like the RPC, we need to define an interface for the client and server to use. This must be in a shared place as both the server and the client need to know about it. You could put this into an SDK and your peers could just get the SDK and implement some function for define and done. The interface definition in the GRPC land could look something like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Greeter is the interface that we&#39;re exposing as a plugin. type Greeter interface {</span></span>
<span class="line"><span>    Greet() string</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// This is the implementation of plugin.GRPCPlugin so we can serve/consume this. type GreeterGRPCPlugin struct {</span></span>
<span class="line"><span>    // GRPCPlugin must still implement the Plugin interface</span></span>
<span class="line"><span>    plugin.Plugin</span></span>
<span class="line"><span>    // Concrete implementation, written in Go. This is only used for plugins</span></span>
<span class="line"><span>    // that are written in Go.</span></span>
<span class="line"><span>    Impl Greeter</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (p *GreeterGRPCPlugin) GRPCServer(broker *plugin.GRPCBroker, s *grpc.Server) error {</span></span>
<span class="line"><span>    proto.RegisterGreeterServer(s, &amp;GRPCServer{Impl: p.Impl})</span></span>
<span class="line"><span>    return nil</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (p *GreeterGRPCPlugin) GRPCClient(ctx context.Context, broker *plugin.GRPCBroker, c *grpc.ClientConn) (interface{}, error) {</span></span>
<span class="line"><span>    return &amp;GRPCClient{client: proto.NewGreeterClient(c)}, nil</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>With this we have the Plugin&#39;s implementation for hashicorp what needed to be done. The plugin will call the underlying implementation and serve/consume the plugin. We can now write the GRPC part of it. Please note that <code>proto</code> is a shared library too where the protocol stubs reside. That needs to be somewhere on the path or in a separate SDK of some sort, but it must be visible.</p><h2 id="writing-the-grpc-client" tabindex="-1">Writing the GRPC Client <a class="header-anchor" href="#writing-the-grpc-client" aria-label="Permalink to &quot;Writing the GRPC Client&quot;">​</a></h2><p>Firstly we define the grpc client struct:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // GRPCClient is an implementation of Greeter that talks over RPC. type GRPCClient struct{ client proto.GreeterClient }</span></span></code></pre></div><p>Then we define how the client will call the remote function:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> func (m *GRPCClient) Greet() string {</span></span>
<span class="line"><span>    ret, _ := m.client.Greet(context.Background(), &amp;proto.Empty{})</span></span>
<span class="line"><span>    return ret.Message</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This will take the <code>client</code> in the <code>GRPCClient</code> and will call the method on it. Once that&#39;s done we will return to the result <code>Message</code> property which will be <code>Hello!</code>. <code>proto.Empty</code> is an empty struct; we use this if there is no parameter for a defined method or no return value. We can&#39;t just leave it blank. <code>protoc</code> needs to be told explicitly that there is no parameter or return value.</p><h2 id="writing-the-grpc-server" tabindex="-1">Writing the GRPC Server <a class="header-anchor" href="#writing-the-grpc-server" aria-label="Permalink to &quot;Writing the GRPC Server&quot;">​</a></h2><p>The server implementation will also be similar. We call <code>Impl</code> here which will have our concrete plugin implementation.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Here is the gRPC server that GRPCClient talks to. type GRPCServer struct {</span></span>
<span class="line"><span>    // This is the real implementation</span></span>
<span class="line"><span>    Impl Greeter</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func (m *GRPCServer) Greet(</span></span>
<span class="line"><span>    ctx context.Context,</span></span>
<span class="line"><span>    req *proto.Empty) *proto.GreeterResponse {</span></span>
<span class="line"><span>    v := m.Impl.Greet()</span></span>
<span class="line"><span>    return &amp;proto.GreeterResponse{Message: v}</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>And we will use the <code>protoc</code> defined message response. <code>v</code> will have the response from <code>Greet</code> which will be <code>Hello!</code> provided by the concrete plugin&#39;s implementation. We then transform that into a protoc type by setting the <code>Message</code> property on the <code>GreeterResponse</code> struct provided by the automatically generated protoc stub code. Easy, right?</p><h2 id="writing-the-plugin-itself" tabindex="-1">Writing the plugin itself <a class="header-anchor" href="#writing-the-plugin-itself" aria-label="Permalink to &quot;Writing the plugin itself&quot;">​</a></h2><p>The whole thing looks much like the RPC implementation with just a few small modifications and changes. This can sit completely outside of everything, or can even be provided by a third party implementor.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // Here is a real implementation of KV that writes to a local file with</span><span> // the key name and the contents are the value of the key. type Greeter struct{}</span></span>
<span class="line"><span>func (Greeter) Greet() error {</span></span>
<span class="line"><span>    return &quot;Hello!&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>func main() {</span></span>
<span class="line"><span>    plugin.Serve(&amp;plugin.ServeConfig{</span></span>
<span class="line"><span>        HandshakeConfig: shared.Handshake,</span></span>
<span class="line"><span>        Plugins: map[string]plugin.Plugin{</span></span>
<span class="line"><span>            &quot;greeter&quot;: &amp;shared.GreeterGRPCPlugin{Impl: &amp;Greeter{}},</span></span>
<span class="line"><span>        },</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // A non-nil value here enables gRPC serving for this plugin...</span></span>
<span class="line"><span>        GRPCServer: plugin.DefaultGRPCServer,</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="calling-it-all-in-the-main" tabindex="-1">Calling it all in the main <a class="header-anchor" href="#calling-it-all-in-the-main" aria-label="Permalink to &quot;Calling it all in the main&quot;">​</a></h2><p>Once all that is done, the <code>main</code> function looks the same as RPC&#39;s main but with some small modifications.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> // We&#39;re a host. Start by launching the plugin process. client := plugin.NewClient(&amp;plugin.ClientConfig{</span></span>
<span class="line"><span>    HandshakeConfig: shared.Handshake,</span></span>
<span class="line"><span>    Plugins:         shared.PluginMap,</span></span>
<span class="line"><span>    Cmd:             exec.Command(&quot;./plugin/greeter&quot;),</span></span>
<span class="line"><span>    AllowedProtocols: []plugin.Protocol{plugin.ProtocolGRPC},</span></span>
<span class="line"><span>})</span></span></code></pre></div><p>The <code>NewClient</code> now defines <code>AllowedProtocols</code> to be <code>ProtocolGRPC</code>. The rest is the same as before calling <code>Dispense</code> and value hinting the plugin to the correct type then calling <code>Greet()</code>.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>This is it. We made it! Now our plugin works over GRPC with a defined API by protoc. The plugin&#39;s implementation can live where ever we want it to, but it needs some shared data. These are:</p><ul><li>The generated code by <code>protoc</code></li><li>The defined plugin interface</li><li>The GRPC Server and Client</li></ul><p>These need to be visible by both the Client and the Server. The Server here is the plugin. If you are planning on making people be able to extend your application with go-plugin, you should make these available as a separate SDK. So people won&#39;t have to include your whole project just to implement an interface and use protoc. In fact, you could also extract the <code>protoc</code> definition into a separate repository so that your SDK can also pull it in. You will have three repositories:</p><ul><li>Your application;</li><li>The SDK providing the interface and the GRPC Server and Client implementation;</li><li>The protoc definition file and generated skeleton ( for Go based plugins).</li></ul><p>Other languages will have to generate their own protoc code, and includ it into the plugin; like the Python implementation example located here: <a href="https://github.com/hashicorp/go-plugin/tree/master/examples/grpc/plugin-python" target="_blank" rel="noreferrer">Go-plugin Python Example</a>. Also, read this documentation carefully: <a href="https://github.com/hashicorp/go-plugin/blob/master/docs/guide-plugin-write-non-go.md" target="_blank" rel="noreferrer">non-go go-plugin</a>. This document will also clarify what <code>1|1|tcp|127.0.0.1:1234|grpc</code> means and will dissipate the confusion around how plugins work. Lastly, if you would like to have an in-depth explanation about how go-plugin came to be, watch this video by Mitchell: <a href="https://www.youtube.com/watch?v=SRvm3zQQc1Q" target="_blank" rel="noreferrer">go-plugin explanation video</a>. I must warn you though- it&#39;s an hour long. But worth the watch!<br> That&#39;s it. I hope this has helped to clear the confusion around how to use go-plugin.</p><p>Happy plugging!</p><p>Gergely.</p>`,105)])])}const g=n(i,[["render",l]]);export{d as __pageData,g as default};
